draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 20);
  ctx.lineTo(W / 2, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 30);
  ctx.lineTo(W / 2 - 20, H / 2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 30);
  ctx.lineTo(W / 2 + 20, H / 2 + 40);
  ctx.stroke();

  // burger
  ctx.beginPath();
  ctx.arc(W / 2 + 50 + 20 * Math.sin(t), H / 2 - 20, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'brown';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W / 2 + 50 + 20 * Math.sin(t), H / 2 - 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'yellow';
  ctx.fill();

  // consequence
  ctx.beginPath();
  ctx.arc(W / 2 - 50 - 20 * Math.sin(t), H / 2 + 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'red';
  ctx.fill();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('?', W / 2 - 50 - 20 * Math.sin(t), H / 2 + 50);

  ctx.restore();
}
